PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS archive_records (
  id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, source_event_id TEXT UNIQUE, title TEXT NOT NULL, node_label TEXT NOT NULL DEFAULT '',
  record_type TEXT NOT NULL DEFAULT 'record', room TEXT NOT NULL DEFAULT '', date_or_period TEXT NOT NULL DEFAULT '', timeline_period TEXT NOT NULL DEFAULT '',
  summary TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', body_html TEXT NOT NULL DEFAULT '', record_status TEXT NOT NULL DEFAULT '',
  state TEXT NOT NULL DEFAULT 'draft' CHECK (state IN ('draft','published','retired','archived')),
  why_it_matters TEXT NOT NULL DEFAULT '', source_note TEXT NOT NULL DEFAULT '', related_notes_json TEXT NOT NULL DEFAULT '[]',
  related_routes_json TEXT NOT NULL DEFAULT '[]', aggregate_attendance INTEGER NOT NULL DEFAULT 0,
  sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
  FOREIGN KEY (id) REFERENCES content_entities(id) ON DELETE CASCADE,
  FOREIGN KEY (source_event_id) REFERENCES events(id) ON DELETE SET NULL
);
CREATE TABLE IF NOT EXISTS archive_collections (id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT 'draft',sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(id) REFERENCES content_entities(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS archive_collection_records (collection_id TEXT NOT NULL,record_id TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,PRIMARY KEY(collection_id,record_id),FOREIGN KEY(collection_id) REFERENCES archive_collections(id) ON DELETE CASCADE,FOREIGN KEY(record_id) REFERENCES archive_records(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS people (id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,bio TEXT NOT NULL DEFAULT '',privacy TEXT NOT NULL DEFAULT 'private' CHECK(privacy IN ('public','unlisted','internal','private')),state TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(id) REFERENCES content_entities(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS places (id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,public_location TEXT NOT NULL DEFAULT '',private_location TEXT NOT NULL DEFAULT '',privacy TEXT NOT NULL DEFAULT 'private' CHECK(privacy IN ('public','unlisted','internal','private')),state TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(id) REFERENCES content_entities(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS archive_record_people (record_id TEXT NOT NULL,person_id TEXT NOT NULL,role TEXT NOT NULL DEFAULT '',public_visible INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(record_id,person_id,role),FOREIGN KEY(record_id) REFERENCES archive_records(id) ON DELETE CASCADE,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS archive_record_places (record_id TEXT NOT NULL,place_id TEXT NOT NULL,role TEXT NOT NULL DEFAULT '',public_visible INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(record_id,place_id,role),FOREIGN KEY(record_id) REFERENCES archive_records(id) ON DELETE CASCADE,FOREIGN KEY(place_id) REFERENCES places(id) ON DELETE CASCADE);

