INSERT OR IGNORE INTO archive_records (id,slug,title,node_label,record_type,room,date_or_period,timeline_period,summary,body,record_status,state,why_it_matters,source_note,related_routes_json,sort_order,created_at,updated_at) VALUES
('process-archive-frame','process-archive-frame','Public Archive Frame','The Six.Well Construct','process','Process','2026','now','The first public archive structure turns process, residue, older forms, and cross-medium evidence into a browsable record layer.','The archive protects the leftovers from being treated like waste. Drafts, screenshots, old labels, process images, event traces, and abandoned structures become usable record instead of noise.','active frame','published','This record marks the point where the archive stops being a placeholder and becomes a repeatable publishing system.','process-archive-frame.md','["/archive/","/about/"]',1,datetime('now'),datetime('now')),
('marbles-source-thread','marbles-source-thread','Marbles Source Thread','Thoughtpuppet / Sai Solehman','artwork','Symbols','2026','now','A painting-source record for recurring symbolic logic: dots, outlined gestures, subconscious action, and the way one work can echo into another.','This source thread tracks a symbolic relationship instead of treating each painting as an isolated object.','source thread','published','This is the kind of record that lets the archive explain lineage without overexplaining the private studio process.','marbles-source-thread.md','["/art/","/archive/"]',2,datetime('now'),datetime('now')),
('coparent-flash-residue','coparent-flash-residue','Co-Parent Flash Residue','Art.Pill Tattoo House','tattoo-flash','Works','2026','now','A flash record kept as evidence of symbolic tattoo language, availability state, and how a design can move between tattooing and archive.','Co-Parent sits in the archive as a flash record and a source-language marker.','reference','published','The record shows that tattoo flash can function as a live offer, a past reference, and a source-language artifact at the same time.','coparent-flash-residue.md','["/tattoos/","/tattoos/flash/","/archive/"]',3,datetime('now'),datetime('now'));

